// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/security/ReentrancyGuard.sol";

contract NetworkProxy is Ownable, ReentrancyGuard {

    struct FeatureFlag {
        bool enabled;
        uint256 activationBlock;
        bytes32 configHash;
    }

    struct AuditEntry {
        address actor;
        bytes32 action;
        bytes32 target;
        uint256 timestamp;
        bytes metadata;
    }

    mapping(bytes32 => FeatureFlag) public features;
    mapping(address => bool) public authorizedRelayers;
    AuditEntry[] public auditLog;

    uint256 public constant MAX_METADATA_LENGTH = 256;
    uint256 public logNonce;

    event FeatureToggled(bytes32 indexed featureId, bool enabled, address toggler);
    event AuditLogged(uint256 indexed entryId, bytes32 indexed action, address actor);
    event RelayExecuted(address indexed target, bool success, bytes32 featureGate);

    modifier onlyRelayer() {
        require(authorizedRelayers[msg.sender] || msg.sender == owner(), "Not authorized");
        _;
    }

    constructor() {
        authorizedRelayers[msg.sender] = true;
    }

    function setRelayer(address relayer, bool status) external onlyOwner {
        authorizedRelayers[relayer] = status;
    }

    function setFeature(bytes32 featureId, bool enabled, uint256 activationBlock, bytes32 configHash) external onlyOwner {
        features[featureId] = FeatureFlag(enabled, activationBlock, configHash);
        _recordAudit(msg.sender, keccak256("FEATURE_SET"), featureId, abi.encodePacked(enabled, activationBlock));
        emit FeatureToggled(featureId, enabled, msg.sender);
    }

    function isFeatureActive(bytes32 featureId) public view returns (bool) {
        FeatureFlag memory flag = features[featureId];
        return flag.enabled && block.number >= flag.activationBlock;
    }

    function relay(address target, bytes calldata payload, bytes32 featureGate) external onlyRelayer nonReentrant returns (bool) {
        require(isFeatureActive(featureGate), "Feature not active");
        require(target != address(this), "Cannot self-call");
        require(target.code.length > 0, "Target not a contract");

        (bool success, bytes memory returnData) = target.call(payload);

        _recordAudit(msg.sender, keccak256("RELAY"), featureGate, _truncateMetadata(returnData));
        emit RelayExecuted(target, success, featureGate);
        return success;
    }

    function batchLog(bytes32[] calldata actions, bytes32[] calldata targets, bytes[] calldata metadataEntries) external onlyRelayer {
        require(actions.length == targets.length && targets.length == metadataEntries.length, "Length mismatch");
        require(actions.length <= 50, "Batch too large");

        for (uint256 i = 0; i < actions.length; i++) {
            _recordAudit(msg.sender, actions[i], targets[i], metadataEntries[i]);
        }
    }

    function getAuditLogLength() external view returns (uint256) {
        return auditLog.length;
    }

    function getAuditRange(uint256 start, uint256 end) external view returns (AuditEntry[] memory) {
        require(end <= auditLog.length && start < end, "Invalid range");
        AuditEntry[] memory entries = new AuditEntry[](end - start);
        for (uint256 i = start; i < end; i++) {
            entries[i - start] = auditLog[i];
        }
        return entries;
    }

    function verifyLogIntegrity(uint256 index) external view returns (bytes32) {
        require(index < auditLog.length, "Index out of bounds");
        AuditEntry memory entry = auditLog[index];
        return keccak256(abi.encodePacked(
            entry.actor,
            entry.action,
            entry.target,
            entry.timestamp,
            entry.metadata
        ));
    }

    function _recordAudit(address actor, bytes32 action, bytes32 target, bytes memory metadata) internal {
        bytes memory safeMetadata = _truncateMetadata(metadata);

        uint256 currentNonce = logNonce;
        logNonce = currentNonce + 1;

        auditLog.push(AuditEntry({
            actor: actor,
            action: action,
            target: target,
            timestamp: block.timestamp,
            metadata: safeMetadata
        }));

        emit AuditLogged(currentNonce, action, actor);
    }

    function _truncateMetadata(bytes memory data) internal pure returns (bytes memory) {
        if (data.length <= MAX_METADATA_LENGTH) {
            return data;
        }
        bytes memory truncated = new bytes(MAX_METADATA_LENGTH);
        for (uint256 i = 0; i < MAX_METADATA_LENGTH; i++) {
            truncated[i] = data[i];
        }
        return truncated;
    }

    function emergencyPurgeLog(uint256 fromIndex) external onlyOwner {
        require(fromIndex < auditLog.length, "Invalid index");
        uint256 originalLength = auditLog.length;
        for (uint256 i = fromIndex; i < originalLength; i++) {
            auditLog.pop();
        }
        _recordAudit(msg.sender, keccak256("EMERGENCY_PURGE"), bytes32(fromIndex), abi.encodePacked(originalLength));
    }

    function delegatedFeatureToggle(bytes32 featureId, bool enabled, bytes calldata authProof) external onlyRelayer {
        require(authProof.length >= 65, "Invalid proof length");

        bytes32 messageHash = keccak256(abi.encodePacked(featureId, enabled, block.chainid, address(this)));
        bytes32 ethSignedHash = keccak256(abi.encodePacked("\x19Ethereum Signed Message:\n32", messageHash));

        (bytes32 r, bytes32 s, uint8 v) = _splitSignature(authProof[:65]);
        address signer = ecrecover(ethSignedHash, v, r, s);
        require(signer == owner(), "Invalid signature");

        FeatureFlag storage flag = features[featureId];
        flag.enabled = enabled;

        // Log the delegated action - relayer is actor but metadata shows delegation
        bytes memory logData = abi.encodePacked(msg.sender, signer, enabled);
        _recordAudit(msg.sender, keccak256("DELEGATED_TOGGLE"), featureId, logData);
        emit FeatureToggled(featureId, enabled, msg.sender);
    }

    function _splitSignature(bytes memory sig) internal pure returns (bytes32 r, bytes32 s, uint8 v) {
        require(sig.length == 65, "Invalid signature length");
        assembly {
            r := mload(add(sig, 32))
            s := mload(add(sig, 64))
            v := byte(0, mload(add(sig, 96)))
        }
    }

    // Feature-gated log export with caller-controlled format descriptor
    function exportLogs(uint256 start, uint256 count, bytes32 formatDescriptor) external view returns (bytes memory) {
        require(isFeatureActive(keccak256("LOG_EXPORT")), "Export feature not active");
        require(start + count <= auditLog.length, "Range exceeds log");

        bytes memory result;
        for (uint256 i = start; i < start + count; i++) {
            AuditEntry memory entry = auditLog[i];
            // formatDescriptor is used as-is in the encoding - allows caller to inject
            // arbitrary bytes32 that gets mixed into the canonical export format
            result = abi.encodePacked(result, formatDescriptor, entry.actor, entry.action, entry.target, entry.timestamp, entry.metadata);
        }
        return result;
    }
}
